INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000201', 'Primeiros passos', 'Como começar a usar o Vimob?', 'A Página inicial reúne atalhos, orientações e o seu foco operacional. Use o menu lateral para entrar em Pipeline, Conversas, Contatos, Agenda, Automações, Dashboard, Gestão e Configurações. Os itens disponíveis variam conforme o plano, o módulo e as permissões do seu usuário.', NULL, NULL, 10, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-comecar-a-usar-o-vimob', 'Conheça a navegação do CRM, os módulos principais e a ordem recomendada para configurar o ambiente.', 'getting-started', '{"primeiro acesso",começar,início,"página inicial",menu,navegação,módulos}', 'all', '/inicio', 'Abrir Página inicial', '[{"id": "inicio-1", "body": "Veja os atalhos disponíveis e o bloco Seu foco agora. Ele usa dados reais do seu acesso e leva diretamente ao lead, tarefa ou compromisso correspondente.", "title": "Comece pela Página inicial", "actionHref": "/inicio", "actionLabel": "Abrir Página inicial"}, {"id": "inicio-2", "body": "Se uma área não aparece no menu, confirme com um administrador se o módulo e a permissão necessários estão liberados para o seu usuário.", "title": "Confira seus acessos", "actionHref": "/settings?tab=team", "actionLabel": "Abrir Configurações"}, {"id": "inicio-3", "body": "Cadastre usuários, configure o pipeline e conecte as integrações que sua operação realmente utiliza antes de iniciar o atendimento.", "title": "Monte a base comercial"}]', '{como-convidar-um-usuario,como-criar-um-lead-no-pipeline,como-conectar-o-whatsapp}', 4, '2026-10-15 03:47:57.224079+00', '''-1'':109C,261C ''-2'':150C,302C ''-3'':189C,341C ''/inicio'':143C,295C ''/set