INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000203', 'Pipeline e leads', 'Como mover um lead entre etapas?', 'No quadro Kanban, arraste o card para a etapa de destino. A mudança é persistida no backend, atualiza o estágio atual e entra no histórico. Dependendo da configuração da etapa, a movimentação também pode iniciar cadências, SLA ou automações.', NULL, NULL, 30, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-mover-um-lead-entre-etapas', 'Mova oportunidades no Kanban e entenda o que pode ser disparado quando o estágio muda.', 'pipeline', '{"mover lead","arrastar card","trocar etapa","mudar estágio",kanban,coluna}', 'all', '/crm/pipelines', 'Abrir Pipeline', '[{"id": "move-1", "body": "Selecione o pipeline correto e use a busca ou os filtros se o card não estiver visível.", "title": "Localize o lead", "actionHref": "/crm/pipelines", "actionLabel": "Abrir Pipeline"}, {"id": "move-2", "body": "Clique e segure o card, mova-o até a coluna desejada e solte. Aguarde a confirmação visual antes de sair da página.", "title": "Arraste para a etapa de destino"}, {"id": "move-3", "body": "Cadências, SLA e automações configuradas para a etapa podem ser aplicadas após a mudança. Abra o detalhe do lead para conferir o histórico e as próximas atividades.", "title": "Revise as consequências"}]', '{como-pesquisar-e-filtrar-leads-no-pipeline,como-configurar-etapas-cadencias-e-sla,como-marcar-um-lead-como-ganho-perdido-ou-reabrir}', 3, '2026-10-15 03:47:57.224079+00', '''-1'':107C,248C ''-2'':137C,278C ''-3'':171C,312C ''/crm/pipelines'':131C,272C ''abra'':187C,328C ''abrir'':133C,274C ''actionhref'':130C,271C ''actionlabel'':132C,273C ''aguard'':153C,294C ''antes'':157C