INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000204', 'Tarefas e cadências', 'Como acompanhar tarefas e cadências?', 'Cadências são sequências de tarefas vinculadas à configuração de uma etapa do pipeline. As atividades aparecem no detalhe do lead e na Agenda. Concluir, reabrir ou registrar o resultado mantém o histórico comercial coerente.', NULL, NULL, 40, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-acompanhar-tarefas-e-cadencias', 'Veja onde as tarefas aparecem, como concluir atividades e como a cadência acompanha o lead.', 'pipeline', '{cadência,cadencias,tarefas,follow-up,ligação,mensagem,"atividade pendente"}', 'all', '/agenda', 'Abrir Agenda', '[{"id": "cadence-view-1", "body": "Abra a Agenda ou o detalhe do lead. Use os filtros de tipo, período e responsável para localizar a atividade correta.", "title": "Consulte as pendências", "actionHref": "/agenda", "actionLabel": "Abrir Agenda"}, {"id": "cadence-view-2", "body": "Ao concluir uma ligação, mensagem, e-mail ou visita, registre o resultado solicitado. Isso evita que uma tarefa seja encerrada sem contexto.", "title": "Execute e registre o resultado"}, {"id": "cadence-view-3", "body": "Uma tarefa concluída pode ser reaberta quando o fluxo permitir. Para mudar a sequência futura, um usuário com permissão de pipeline deve editar a configuração da etapa.", "title": "Corrija quando necessário"}]', '{como-configurar-etapas-cadencias-e-sla,como-criar-e-editar-um-agendamento}', 4, '2026-10-15 03:47:57.224079+00', '''/agenda'':130C,275C ''1'':102C,247C ''2'':138C,283C ''3'':173C,318C ''abra'':104C,249C ''abrir'':132C,277C ''acompanh'':2A,7A,23B,48B ''actionhref'':129C,274C ''actionlabel'':131C,276C ''a