INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000206', 'Conversas e WhatsApp', 'Como usar Conversas no Vimob?', 'A tela Conversas reúne atendimentos das conexões de WhatsApp acessíveis ao usuário. É possível pesquisar, filtrar, ler o histórico, enviar mensagens, trabalhar com mídia e abrir o lead relacionado sem perder o contexto.', NULL, NULL, 60, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-usar-conversas-no-vimob', 'Selecione a conexão, encontre um atendimento e use o histórico e os filtros de Conversas.', 'conversations', '{conversas,whatsapp,chat,atendimento,mensagens,"buscar conversa",histórico}', 'all', '/crm/conversas', 'Abrir Conversas', '[{"id": "conversation-1", "body": "Quando houver mais de uma sessão disponível, escolha a conexão que atende o canal desejado.", "title": "Selecione a conexão", "actionHref": "/crm/conversas", "actionLabel": "Abrir Conversas"}, {"id": "conversation-2", "body": "Busque por contato, nome, telefone, texto ou identificador. Combine filtros de grupos, arquivadas, somente leads, sem lead ou aguardando resposta.", "title": "Pesquise ou filtre"}, {"id": "conversation-3", "body": "Selecione a conversa e carregue mensagens antigas quando necessário. Marque a conversa como lida depois de revisar o contexto.", "title": "Abra o histórico"}, {"id": "conversation-4", "body": "Quando a conversa está vinculada, abra o lead no Pipeline. Se não estiver, cadastre o contato a partir da própria conversa quando tiver permissão.", "title": "Use o painel do lead"}]', '{como-conectar-o-whatsapp,como-enviar-texto-audio-e-arquivos-no-whatsapp,como-abrir-e-entender-o-detalhe-de-um-lead}', 5, '2026-10-15 03:47:57.224079+00', '''-1'':95C,248