INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000207', 'Imóveis', 'Como cadastrar e publicar imóveis?', 'O cadastro de imóvel organiza proprietário, dados gerais, localização, valores, características, extras, mídia, descrição, publicação, comissões e informações confidenciais. Os recursos disponíveis dependem do segmento, módulo e permissões da organização.', NULL, NULL, 70, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-cadastrar-e-publicar-imoveis', 'Cadastre um imóvel completo e revise os dados necessários antes de publicar no site.', 'properties', '{imóvel,imoveis,"cadastrar imóvel","publicar imóvel",fotos,proprietário,site}', 'all', '/properties/new', 'Cadastrar imóvel', '[{"id": "property-1", "body": "Em Imóveis, escolha Novo imóvel. O link abaixo abre diretamente o formulário quando o módulo está disponível.", "title": "Abra o cadastro", "actionHref": "/properties/new", "actionLabel": "Cadastrar imóvel"}, {"id": "property-2", "body": "Informe proprietário, tipo, localização, valores, características e descrições. Salve dados consistentes para facilitar busca e publicação.", "title": "Preencha os blocos do formulário"}, {"id": "property-3", "body": "Envie fotos adequadas, escolha a ordem e revise o conteúdo que ficará visível no site.", "title": "Adicione mídia com contexto"}, {"id": "property-4", "body": "Antes de publicar, confira status, campos confidenciais, condições comerciais e a configuração do site da organização.", "title": "Revise a publicação"}]', '{como-comecar-a-usar-o-vimob}', 6, '2026-10-15 03:47:57.224079+00', '''-1'':90C,225C ''-2'':120C,255C ''-3'':146C,281C ''-4'':170C,305C ''/properties/new'':114C,249C ''abaix'':99C,234C ''abra'