INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000209', 'Gestão e distribuição', 'Como funciona a distribuição de leads?', 'A distribuição usa filas e regras para encaminhar oportunidades a usuários ou equipes. Pesos, disponibilidade, origem e critérios configurados influenciam o destino. O backend registra o histórico da atribuição e respeita o escopo da organização.', NULL, NULL, 90, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-funciona-a-distribuicao-de-leads', 'Entenda filas, participantes, pesos e regras usadas para atribuir novas oportunidades.', 'management', '{distribuição,roleta,"round robin",fila,peso,atribuição,responsável}', 'all', '/crm/management?tab=distribution', 'Abrir Distribuição', '[{"id": "distribution-1", "body": "Em Gestão, escolha Distribuição. A edição exige a permissão correspondente.", "title": "Abra a área de Distribuição", "actionHref": "/crm/management?tab=distribution", "actionLabel": "Abrir Distribuição"}, {"id": "distribution-2", "body": "Inclua apenas usuários que realmente atendem aquele fluxo e ajuste pesos de forma consciente.", "title": "Defina participantes e pesos"}, {"id": "distribution-3", "body": "Use origem, campanha, tag ou outras condições disponíveis para encaminhar cada entrada à fila correta.", "title": "Configure critérios"}, {"id": "distribution-4", "body": "Confira o responsável no lead e use o histórico de distribuição para investigar uma atribuição inesperada.", "title": "Acompanhe o resultado"}]', '{como-criar-e-gerenciar-equipes,como-atribuir-ou-redistribuir-um-lead}', 5, '2026-10-15 03:47:57.224079+00', '''-1'':91C,225C ''-2'':118C,252C ''-3'':141C,275C ''-4'':163C,297C ''/crm/management'':110C,244C