INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000210', 'Dashboard', 'Como usar os filtros do Dashboard?', 'O Dashboard geral apresenta indicadores comerciais conforme o período e o escopo de acesso. Os filtros podem incluir time, usuário, origem, campanha, conjunto, anúncio, tag, status e pesquisa. Dashboard de campanhas e Dashboard do site possuem permissões próprias.', NULL, NULL, 100, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-usar-os-filtros-do-dashboard', 'Aplique filtros para analisar o mesmo recorte em KPIs, funil, evolução e origens.', 'dashboard', '{dashboard,painel,filtros,período,equipe,corretor,origem,campanha}', 'all', '/dashboard', 'Abrir Dashboard', '[{"id": "dashboard-filter-1", "body": "Escolha o intervalo analisado antes de comparar indicadores. Alguns números consideram a data de captação; outros, a data em que o negócio foi ganho ou perdido.", "title": "Defina o período", "actionHref": "/dashboard", "actionLabel": "Abrir Dashboard"}, {"id": "dashboard-filter-2", "body": "Use time, usuário, origem, campanha, anúncio, tag, status ou pesquisa conforme sua permissão.", "title": "Aplique o recorte operacional"}, {"id": "dashboard-filter-3", "body": "Compare KPIs, funil por pipeline, evolução e origens. Clicar em uma origem ou detalhe pode abrir o recorte correspondente.", "title": "Leia o conjunto completo"}, {"id": "dashboard-filter-4", "body": "Os números refletem somente os leads que seu papel permite visualizar.", "title": "Respeite o escopo"}]', '{o-que-significam-os-kpis-do-dashboard}', 5, '2026-10-15 03:47:57.224079+00', '''/dashboard'':131C,286C ''1'':98C,253C ''2'':139C,294C ''3'':163C,318C ''4'':193C,348C ''abrir'':133C,180C,28