INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000211', 'Notificações', 'Como acompanhar notificações?', 'O sino no cabeçalho mostra avisos recentes e a quantidade não lida. A página de Notificações reúne a lista completa. Quando um aviso possui destino válido, selecioná-lo abre diretamente o item relacionado.', NULL, NULL, 110, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-acompanhar-notificacoes', 'Consulte avisos, marque itens como lidos e abra o destino relacionado.', 'notifications', '{notificações,sino,avisos,"não lidas",push,alertas}', 'all', '/notifications', 'Abrir Notificações', '[{"id": "notification-1", "body": "Use o contador no cabeçalho para ver os avisos mais recentes.", "title": "Abra o sino"}, {"id": "notification-2", "body": "Na página Notificações, revise os itens não lidos e use as ações disponíveis.", "title": "Consulte a lista completa", "actionHref": "/notifications", "actionLabel": "Abrir Notificações"}, {"id": "notification-3", "body": "Quando houver um link de destino, selecione a notificação para ir ao lead, tarefa, conversa ou configuração relacionada.", "title": "Abra o contexto"}]', '{como-comecar-a-usar-o-vimob}', 3, '2026-10-15 03:47:57.224079+00', '''-1'':80C,187C ''-2'':99C,206C ''-3'':126C,233C ''/notifications'':120C,227C ''abra'':14B,32B,94C,147C,201C,254C ''abre'':73C,180C ''abrir'':122C,229C ''aco'':219C ''acompanh'':2A,5A ''actionhref'':119C,226C ''actionlabel'':121C,228C ''alert'':24B,42B ''avis'':8B,20B,26B,38B,49C,66C,90C,156C,173C,197C ''açõ'':112C ''body'':81C,100C,127C,188C,207C,234C ''cabecalh'':154C,193C ''cabeçalh'':47C,86C ''complet'':63C,118C,170C,225C ''configur'':144C ''configuraca'':251C ''consult'':7B