INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000212', 'Contatos', 'Como gerenciar contatos?', 'Contatos é a visão pesquisável da base de leads da organização. A tela permite filtrar, ordenar, paginar, criar, abrir, importar, exportar e excluir conforme o escopo e as permissões do usuário.', NULL, NULL, 120, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-gerenciar-contatos', 'Pesquise a base, aplique filtros e abra o detalhe completo de uma pessoa ou oportunidade.', 'contacts', '{contatos,"lista de leads",base,"buscar pessoa",telefone,email}', 'all', '/crm/contacts', 'Abrir Contatos', '[{"id": "contacts-1", "body": "Use nome, telefone ou e-mail. A busca acontece no backend e respeita seu escopo de visualização.", "title": "Pesquise a base", "actionHref": "/crm/contacts", "actionLabel": "Abrir Contatos"}, {"id": "contacts-2", "body": "Combine período, time, pipeline, etapa, responsável, tag, origem, campanha e status conforme necessário.", "title": "Refine os resultados"}, {"id": "contacts-3", "body": "Selecione um contato para revisar dados, negócio, agenda, atividades e histórico.", "title": "Abra o detalhe"}, {"id": "contacts-4", "body": "Importação, exportação e exclusão aparecem somente para quem possui as permissões correspondentes.", "title": "Use ações em massa com cuidado"}]', '{como-importar-contatos,como-exportar-contatos-em-csv,como-abrir-e-entender-o-detalhe-de-um-lead}', 5, '2026-10-15 03:47:57.224079+00', '''-1'':89C,215C ''-2'':120C,246C ''-3'':141C,267C ''-4'':160C,286C ''/crm/contacts'':114C,240C ''abra'':13B,37B,155C,281C ''abrir'':74C,116C,200C,242C ''aco'':302C ''acontec'':100C,226C ''actionhref'':113C,239C ''actionlabel'':115C,241C ''a