INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000213', 'Equipes e permissões', 'Como criar e gerenciar equipes?', 'A área Equipes organiza membros, líderes, disponibilidade e vínculos com pipelines. Ela é diferente da tela Usuários, onde são enviados convites e configuradas permissões individuais.', NULL, NULL, 130, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.224079+00', 'como-criar-e-gerenciar-equipes', 'Monte times operacionais, defina liderança e vincule os pipelines corretos.', 'management', '{equipes,times,líder,membros,"pipeline da equipe",disponibilidade}', 'all', '/crm/management?tab=teams', 'Abrir Equipes', '[{"id": "team-1", "body": "A criação e edição dependem da permissão de gestão de equipes.", "title": "Abra Equipes em Gestão", "actionHref": "/crm/management?tab=teams", "actionLabel": "Abrir Equipes"}, {"id": "team-2", "body": "Inclua usuários ativos, marque a liderança correta e revise a disponibilidade de quem participa da operação.", "title": "Defina membros e liderança"}, {"id": "team-3", "body": "Associe somente os pipelines que o time precisa acompanhar. Isso influencia visibilidade e distribuição.", "title": "Vincule pipelines"}, {"id": "team-4", "body": "Para convidar uma pessoa ou alterar permissões individuais, use Configurações > Usuários.", "title": "Separe equipe de acesso"}]', '{como-convidar-um-usuario,como-configurar-permissoes-e-remover-usuarios,como-funciona-a-distribuicao-de-leads}', 5, '2026-10-15 03:47:57.224079+00', '''-1'':77C,198C ''-2'':104C,225C ''-3'':129C,250C ''-4'':150C,271C ''/crm/management'':96C,217C ''abra'':91C,212C ''abrir'':100C,221C ''acess'':167C,288C ''acompanh'':139C,260C ''actionhref'':95C,216C ''actionlabel'':99C,2