INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000214', 'Pipeline e leads', 'Como abrir e entender o detalhe de um lead?', 'O detalhe do lead centraliza contato, negócio, atividades, agenda e histórico. Também pode mostrar tags, imóveis de interesse, anexos, feedback, responsável, cadência e ações comerciais conforme as permissões.', NULL, NULL, 140, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-abrir-e-entender-o-detalhe-de-um-lead', 'Abra uma oportunidade e entenda onde consultar contato, negócio, agenda e histórico.', 'pipeline', '{"detalhe do lead","histórico lead","perfil lead",atividades,feedback,anexos,"agenda lead"}', 'all', '/crm/pipelines', 'Abrir Pipeline', '[{"id": "lead-detail-1", "body": "No Pipeline, Contatos, Conversas ou Página inicial, selecione o lead. Links diretos usam /crm/pipelines?lead={id}.", "title": "Abra o card ou um resultado de busca", "actionHref": "/crm/pipelines", "actionLabel": "Abrir Pipeline"}, {"id": "lead-detail-2", "body": "Confira nome, telefone, e-mail, origem, pipeline, etapa, responsável, valor e imóveis de interesse antes de alterar qualquer informação.", "title": "Revise contato e negócio"}, {"id": "lead-detail-3", "body": "Use atividades, agenda, resultados de contato, tags, feedback e anexos para manter o contexto compartilhado.", "title": "Registre a operação"}, {"id": "lead-detail-4", "body": "O histórico ajuda a entender mensagens, mudanças de etapa, responsáveis, tarefas e outras ações já registradas.", "title": "Consulte o histórico"}]', '{como-criar-um-lead-no-pipeline,como-marcar-um-lead-como-ganho-perdido-ou-reabrir,como-atribuir-ou-redistribuir-um-lead}', 5, '2026-10-15 03:47:57.224079+00', '''/crm/pi