INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000216', 'Pipeline e leads', 'Como configurar etapas, cadências e SLA?', 'As configurações de etapas ficam no próprio Pipeline. Usuários com permissão de gestão de pipeline podem criar, renomear, colorir, reordenar ou excluir etapas, configurar tarefas de cadência, automações de etapa e regras de SLA.', NULL, NULL, 160, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-configurar-etapas-cadencias-e-sla', 'Ajuste as colunas do funil e defina o acompanhamento que começa quando o lead entra em uma etapa.', 'pipeline', '{etapas,colunas,"cadência por etapa",sla,"automação de etapa","renomear etapa","ordenar etapas"}', 'authenticated', '/crm/pipelines', 'Abrir Pipeline', '[{"id": "stage-1", "body": "Selecione o pipeline e use a ação de configuração disponível para usuários com pipeline_manage.", "title": "Abra as configurações do Pipeline", "actionHref": "/crm/pipelines", "actionLabel": "Abrir Pipeline"}, {"id": "stage-2", "body": "Crie, renomeie, escolha cores e reordene as colunas para representar o processo real da equipe.", "title": "Organize as etapas"}, {"id": "stage-3", "body": "Adicione as tarefas que devem nascer quando o lead entra na etapa. Não existe hoje uma aba autônoma de Cadências na Gestão.", "title": "Configure a cadência da etapa"}, {"id": "stage-4", "body": "Configure automações de etapa somente com o módulo disponível e defina os tempos de SLA que fazem sentido para aquele estágio.", "title": "Revise automações e SLA"}]', '{como-acompanhar-tarefas-e-cadencias,como-mover-um-lead-entre-etapas,como-criar-uma-automacao}', 6, '2026-10-15 03:47:57.224079+00', '''-1'':114C,266C ''-2'':144C,296C ''-3'':167C