INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000220', 'Conversas e WhatsApp', 'Como enviar texto, áudio e arquivos no WhatsApp?', 'O compositor de Conversas permite texto, imagem, vídeo, áudio gravado e documentos. Também é possível reagir a mensagens e repetir o envio de mídia quando a ação estiver disponível.', NULL, NULL, 200, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-enviar-texto-audio-e-arquivos-no-whatsapp', 'Envie mensagens e mídias mantendo o atendimento vinculado ao lead correto.', 'conversations', '{"enviar mensagem","áudio whatsapp",imagem,vídeo,arquivo,documento,"gravar áudio",reagir}', 'all', '/crm/conversas', 'Abrir Conversas', '[{"id": "message-1", "body": "Antes de enviar, revise o contato aberto e a sessão selecionada.", "title": "Confirme conversa e conexão", "actionHref": "/crm/conversas", "actionLabel": "Abrir Conversas"}, {"id": "message-2", "body": "Digite texto ou use as ações de anexo e áudio. Confira arquivo, tamanho e destinatário.", "title": "Escolha o formato"}, {"id": "message-3", "body": "Não repita imediatamente. Observe o estado da mensagem e use repetir somente quando houver indicação de falha.", "title": "Envie e aguarde o estado"}, {"id": "message-4", "body": "Cadastre ou abra o lead relacionado para preservar histórico, tags, agenda e automações do atendimento.", "title": "Mantenha o lead vinculado"}]', '{como-usar-conversas-no-vimob,como-conectar-o-whatsapp}', 4, '2026-10-15 03:47:57.224079+00', '''-1'':95C,226C ''-2'':120C,251C ''-3'':143C,274C ''-4'':170C,301C ''/crm/conversas'':114C,245C ''abert'':103C,234C ''abra'':174C,305C ''abrir'':116C,247C ''aca'':221C ''aco'':258C ''actionhref'':113C,244C ''actionlabel''