INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000221', 'Automações', 'Como criar uma automação a partir de um modelo?', 'Modelos ajudam a iniciar um fluxo com uma estrutura pronta. Eles não eliminam a revisão: confira gatilho, conexão, mensagens, esperas, condições, tags, etapas e variáveis antes de salvar e ativar.', NULL, NULL, 210, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-criar-uma-automacao-a-partir-de-um-modelo', 'Escolha um modelo, adapte cada bloco ao processo e valide antes de ativar.', 'automations', '{"modelo de automação","template automação","follow-up pronto","duplicar fluxo"}', 'all', '/automations?tab=templates', 'Ver modelos', '[{"id": "template-1", "body": "Consulte os modelos disponíveis e escolha o ponto de partida mais próximo do seu objetivo.", "title": "Abra Modelos", "actionHref": "/automations?tab=templates", "actionLabel": "Ver modelos"}, {"id": "template-2", "body": "Troque mensagens, sessão do WhatsApp, tempos de espera, condições, tags e etapas que não pertencem ao seu processo.", "title": "Revise todos os blocos"}, {"id": "template-3", "body": "Teste respostas e condições no simulador para localizar blocos desconectados ou inválidos.", "title": "Simule os caminhos"}, {"id": "template-4", "body": "O modelo só deve entrar em produção depois da revisão completa.", "title": "Salve e ative conscientemente"}]', '{como-criar-uma-automacao,como-acompanhar-execucoes-e-erros-de-automacao}', 5, '2026-10-15 03:47:57.224079+00', '''-1'':100C,227C ''-2'':129C,256C ''-3'':156C,283C ''-4'':176C,303C ''/automations'':121C,248C ''abra'':118C,245C ''actionhref'':120C,247C ''actionlabel'':124C,251C ''adapt'':22B,46B ''ajud'':69C,196C ''antes