INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000222', 'Automações', 'Como acompanhar execuções e erros de automação?', 'A aba Histórico mostra execuções, etapas percorridas, falhas e ações disponíveis. Usuários autorizados podem cancelar execuções em andamento e tentar novamente operações compatíveis.', NULL, NULL, 220, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-acompanhar-execucoes-e-erros-de-automacao', 'Use o Histórico para entender uma execução, cancelar um fluxo ou investigar uma falha.', 'automations', '{"histórico automação","execução automação","erro automação",falha,retry,"tentar novamente",saúde}', 'all', '/automations?tab=history', 'Abrir Histórico', '[{"id": "automation-history-1", "body": "A antiga aba Saúde foi incorporada ao Histórico. Use filtros para localizar a automação, o lead ou o estado da execução.", "title": "Abra Histórico", "actionHref": "/automations?tab=history", "actionLabel": "Abrir Histórico"}, {"id": "automation-history-2", "body": "Confira o gatilho, cada etapa, horários, tentativas e a mensagem de erro apresentada.", "title": "Abra a execução"}, {"id": "automation-history-3", "body": "Cancele uma execução ainda ativa ou tente novamente somente quando a causa já estiver corrigida.", "title": "Decida a ação"}, {"id": "automation-history-4", "body": "Se a falha se repetir, edite a automação e revise sessão, mídia, webhook, variável ou conexão envolvida.", "title": "Corrija o fluxo na origem"}]', '{como-criar-uma-automacao,como-criar-uma-automacao-a-partir-de-um-modelo}', 5, '2026-10-15 03:47:57.224079+00', '''/automations'':120C,258C ''1'':93C,231C ''2'':130C,268C ''3'':153C,291C ''4'':178C,316C ''aba'':67C,97C,205C,235C