INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000223', 'Agenda', 'Como conectar o Google Agenda?', 'A integração fica dentro da Agenda. Usuários autorizados podem conectar ou desconectar a conta Google. Compromissos criados, alterados ou excluídos no Vimob são enviados ao Google Agenda. Eventos criados ou alterados no Google não entram no Vimob.', NULL, NULL, 230, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:53:14.102712+00', 'como-conectar-o-google-agenda', 'Conecte sua conta Google para enviar compromissos criados no Vimob à sua agenda.', 'schedule', '{"google agenda","google calendar","sincronizar agenda","conectar calendário",oauth}', 'all', '/agenda', 'Abrir Agenda', '[{"id": "google-1", "body": "Na barra da Agenda, selecione Google Agenda.", "title": "Abra Google Agenda", "actionHref": "/agenda", "actionLabel": "Abrir Agenda"}, {"id": "google-2", "body": "Confira qual conta Google está aberta antes de aceitar o acesso.", "title": "Autorize a conta correta"}, {"id": "google-3", "body": "Depois de conectar, crie ou altere um compromisso de teste no Vimob e confira o resultado no Google Agenda.", "title": "Teste um compromisso"}, {"id": "google-4", "body": "Exclua o compromisso de teste no Vimob e confirme a remoção do evento vinculado no Google após o processamento.", "title": "Teste a exclusão"}]', '{como-criar-e-editar-um-agendamento}', 4, '2026-10-15 03:53:14.102712+00', '''-1'':95C,227C ''-2'':115C,247C ''-3'':135C,267C ''-4'':162C,294C ''/agenda'':109C,241C ''abert'':122C,254C ''abra'':105C,237C ''abrir'':111C,243C ''aceit'':125C,257C ''acess'':127C,259C ''actionhref'':108C,240C ''actionlabel'':110C,242C ''agend'':5A,10A,23B,25B,29B,45B,47B,51B,55C,61C,82C,100C,103C,10