INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000225', 'Usuários e permissões', 'Como configurar permissões e remover usuários?', 'A tela individual permite alterar permissões específicas e restaurar o padrão. Ao excluir um usuário, o Vimob mostra o impacto e pode exigir a transferência de leads e imóveis para outro usuário ativo. Conexões de WhatsApp são desconectadas, não transferidas.', NULL, NULL, 250, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-configurar-permissoes-e-remover-usuarios', 'Ajuste acessos individuais e transfira responsabilidades antes de remover uma pessoa.', 'users', '{permissões,"acesso usuário","remover usuário","excluir usuário","transferir leads","desativar usuário"}', 'authenticated', '/settings?tab=team', 'Abrir Usuários', '[{"id": "permission-1", "body": "Em Configurações > Usuários, selecione a pessoa. A tela de permissões exige permissions_manage.", "title": "Abra o usuário", "actionHref": "/settings?tab=team", "actionLabel": "Abrir Usuários"}, {"id": "permission-2", "body": "Salve somente os acessos necessários. Use restaurar quando quiser voltar ao padrão da função.", "title": "Ajuste ou restaure"}, {"id": "permission-3", "body": "Desativar preserva o registro e bloqueia o uso sem executar a exclusão definitiva.", "title": "Desative quando for temporário"}, {"id": "permission-4", "body": "Revise a contagem de impacto e escolha outro usuário ativo para receber leads e imóveis. Confirme também o efeito sobre sessões de WhatsApp.", "title": "Transfira antes de excluir"}]', '{como-convidar-um-usuario,como-criar-e-gerenciar-equipes}', 6, '2026-10-15 03:47:57.224079+00', '''-1'':102C,249C ''-2'':130C,277C ''-3'':152C,299C ''-4'