INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000226', 'Pipeline e leads', 'Como marcar um lead como ganho, perdido ou reabrir?', 'O status comercial é independente da coluna do Pipeline. Marcar como ganho registra a conclusão positiva; marcar como perdido exige o motivo; reabrir devolve a oportunidade ao fluxo ativo. Todas as ações entram no histórico.', NULL, NULL, 260, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-marcar-um-lead-como-ganho-perdido-ou-reabrir', 'Registre corretamente o resultado comercial sem perder o histórico da oportunidade.', 'pipeline', '{"lead ganho","lead perdido","reabrir lead","motivo de perda",venda,"status do negócio"}', 'all', '/crm/pipelines', 'Abrir Pipeline', '[{"id": "deal-status-1", "body": "Selecione o card e revise o negócio antes de alterar o resultado.", "title": "Abra o lead", "actionHref": "/crm/pipelines", "actionLabel": "Abrir Pipeline"}, {"id": "deal-status-2", "body": "Use a ação disponível no detalhe. Para perda, informe um motivo que ajude a análise comercial.", "title": "Escolha ganho ou perdido"}, {"id": "deal-status-3", "body": "Valide quem alterou, quando e qual motivo foi registrado.", "title": "Confira o histórico"}, {"id": "deal-status-4", "body": "Use reabrir em vez de criar um lead duplicado quando o mesmo negócio retomar o atendimento.", "title": "Reabra quando a oportunidade voltar"}]', '{como-abrir-e-entender-o-detalhe-de-um-lead,o-que-significam-os-kpis-do-dashboard}', 4, '2026-10-15 03:47:57.224079+00', '''/crm/pipelines'':128C,267C ''1'':109C,248C ''2'':136C,275C ''3'':163C,302C ''4'':182C,321C ''abra'':124C,263C ''abrir'':130C,269C ''aca'':279C ''aco'':240C ''actionhref'':127C,266C ''actionla