INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000227', 'Pipeline e leads', 'Como atribuir ou redistribuir um lead?', 'Usuários autorizados podem selecionar um responsável, limpar a atribuição ou solicitar redistribuição pela fila configurada. A ação respeita organização, equipe, disponibilidade e regras de acesso.', NULL, NULL, 270, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-atribuir-ou-redistribuir-um-lead', 'Troque o responsável ou use a distribuição configurada sem perder o histórico.', 'pipeline', '{"atribuir lead",responsável,"redistribuir lead","trocar corretor","limpar responsável",roleta}', 'authenticated', '/crm/pipelines', 'Abrir Pipeline', '[{"id": "assign-1", "body": "Confira responsável atual, equipe e pipeline antes da mudança.", "title": "Abra o detalhe do lead", "actionHref": "/crm/pipelines", "actionLabel": "Abrir Pipeline"}, {"id": "assign-2", "body": "Selecione outro responsável, limpe a atribuição ou use Redistribuir para aplicar a fila disponível.", "title": "Escolha a ação"}, {"id": "assign-3", "body": "Revise o novo responsável e o histórico. Uma redistribuição pode considerar peso e disponibilidade.", "title": "Confirme o destino"}]', '{como-funciona-a-distribuicao-de-leads,como-abrir-e-entender-o-detalhe-de-um-lead}', 4, '2026-10-15 03:47:57.224079+00', '''-1'':87C,183C ''-2'':111C,207C ''-3'':133C,229C ''/crm/pipelines'':105C,201C ''abra'':99C,195C ''abrir'':107C,203C ''aca'':172C,226C ''acess'':84C,180C ''actionhref'':104C,200C ''actionlabel'':106C,202C ''antes'':95C,191C ''aplic'':123C,219C ''assign'':86C,110C,132C,182C,206C,228C ''atribu'':2A,8A,25B,47B ''atribuica'':164C,214C ''atribuiçã'':68C,118C ''atual'':91C,187C ''aut