INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000228', 'Dashboard', 'O que significam os KPIs do Dashboard?', 'O Dashboard geral pode mostrar Leads, Em aberto, Perdidos, Ganhos, Visitas, VGV, 1º Contato, Imóveis e Visitas no site. Cada indicador depende do período, dos filtros, do módulo e da permissão do usuário.', NULL, NULL, 280, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'o-que-significam-os-kpis-do-dashboard', 'Entenda o significado dos indicadores realmente exibidos no Dashboard do Vimob.', 'dashboard', '{kpi,indicadores,leads,"em aberto",perdidos,ganhos,visitas,vgv,"primeiro contato"}', 'all', '/dashboard', 'Abrir Dashboard', '[{"id": "kpi-1", "body": "Leads representa o volume captado no recorte. Em aberto representa oportunidades ainda ativas conforme os filtros.", "title": "Leads e Em aberto"}, {"id": "kpi-2", "body": "Ganhos e Perdidos usam o resultado comercial. VGV soma os valores considerados pelo recorte de negócios ganhos.", "title": "Ganhos, Perdidos e VGV"}, {"id": "kpi-3", "body": "Visitas dependem das atividades registradas. 1º Contato mede o atendimento inicial conforme a instrumentação do CRM.", "title": "Visitas e 1º Contato"}, {"id": "kpi-4", "body": "Esses indicadores aparecem quando os módulos e permissões correspondentes estão disponíveis.", "title": "Imóveis e Visitas no site", "actionHref": "/dashboard", "actionLabel": "Abrir Dashboard"}]', '{como-usar-os-filtros-do-dashboard}', 5, '2026-10-15 03:47:57.224079+00', '''-1'':95C,231C ''-2'':120C,256C ''-3'':146C,282C ''-4'':171C,307C ''/dashboard'':191C,327C ''1º'':72C,153C,167C,208C,289C,303C ''abert'':30B,52B,67C,105C,117C,203C,241C,253C ''abrir'':193C,329C ''actionhref'':190C,326