INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000229', 'Integrações', 'Como conectar a integração Meta?', 'A integração Meta é configurada em Configurações > Integrações. O fluxo autoriza a conta, seleciona páginas e formulários e mapeia o destino dos leads. O acesso depende do módulo e das permissões da organização.', NULL, NULL, 290, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-conectar-a-integracao-meta', 'Autorize a Meta, selecione páginas e formulários e revise o destino de cada lead.', 'integrations', '{meta,facebook,instagram,"lead ads","formulário meta","conectar facebook"}', 'all', '/settings?tab=integrations', 'Abrir Integrações', '[{"id": "meta-1", "body": "Em Configurações, selecione Integrações e localize Meta.", "title": "Abra Integrações", "actionHref": "/settings?tab=integrations", "actionLabel": "Abrir Integrações"}, {"id": "meta-2", "body": "Confira o perfil e a empresa antes de concluir o OAuth.", "title": "Autorize a conta correta"}, {"id": "meta-3", "body": "Escolha somente as fontes que devem alimentar o CRM.", "title": "Selecione página e formulários"}, {"id": "meta-4", "body": "Defina pipeline, etapa, equipe ou responsável e valide a chegada de um lead de teste.", "title": "Mapeie e teste"}]', '{como-funciona-a-distribuicao-de-leads,como-criar-um-lead-no-pipeline}', 6, '2026-10-15 03:47:57.224079+00', '''-1'':93C,209C ''-2'':114C,230C ''-3'':134C,250C ''-4'':152C,268C ''/settings'':106C,222C ''abra'':103C,219C ''abrir'':110C,226C ''acess'':82C,198C ''actionhref'':105C,221C ''actionlabel'':109C,225C ''ads'':29B,52B ''aliment'':142C,258C ''antes'':122C,238C ''autoriz'':11B,34B,68C,128C,184C,244C ''body'':94C,115C,135C,153C,210C,231C