INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000230', 'Integrações e API', 'Como criar uma chave de API e configurar webhooks?', 'As chaves emitidas nesta tela são credenciais reservadas às integrações que a Vimob liberar explicitamente. Elas não substituem o login do usuário e não tornam públicos os endpoints internos do CRM. Webhooks enviam eventos selecionados para uma URL configurada. Trate toda credencial como segredo e valide cada evento recebido.', NULL, NULL, 300, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.224079+00', 'como-criar-chave-de-api-e-configurar-webhooks', 'Entenda o escopo atual das credenciais e configure entregas de eventos com segurança.', 'integrations', '{api,"chave api",token,webhook,integração,"documentação api",endpoint}', 'authenticated', '/settings?tab=api', 'Abrir chaves de API', '[{"id": "api-1", "body": "Uma chave cadastrada não libera, sozinha, os endpoints internos do CRM. Antes de desenvolver, confirme com a Vimob quais rotas e escopos estão disponíveis para sua organização.", "title": "Confirme se a integração foi liberada"}, {"id": "api-2", "body": "Em Configurações, entre em API. Se a integração estiver liberada, gere a chave, copie-a no momento indicado e armazene-a em um cofre de segredos. Nunca coloque uma chave em frontend, código público ou mensagem.", "title": "Abra e proteja as credenciais", "actionHref": "/settings?tab=api", "actionLabel": "Abrir chaves de API"}, {"id": "api-3", "body": "Use uma URL HTTPS, escolha os eventos necessários e mantenha o receptor idempotente.", "title": "Configure o webhook"}, {"id": "api-4", "body": "Confirme autenticação, payload, resposta e reentregas em um ambiente seguro antes de ativar a integração em produção.", "title": "Teste somente contra o contrato liberado"}]', '{como-comecar-a-usar-o-vimob}', 6, '2026-10-15 03:47:57.224079+00', '''-1'':117C,313C ''-2'':155C,351C ''-3'':212C,408C ''-4'':233C,429C ''/settings'':202C,398C ''abra'':196C,392C ''abrir'':206C,402C ''actionhref'':201C,397C ''actionlabel'':205C,401C ''ambient'':243C,439C ''antes'':130C,245C,326C,441C ''api'':6A,15A,32B,34B,39B,54B,56B,61B,65C,116C,154C,161C,204C,209C,211C,232C,261C,312C,350C,357C,400C,405C,407C,428C ''armazen'':178C,374C ''armazene-'':177C,373C ''ativ'':247C,443C ''atual'':22B,44B ''autentic'':236C ''autenticaca'':432C ''body'':118C,156C,213C,234C,314C,352C,409C,430C ''cad'':112C,308C ''cadastr'':121C,317C ''chav'':4A,13A,33B,55B,67C,120C,169C,188C,207C,263C,316C,365C,384C,403C ''codig'':387C ''cofr'':182C,378C ''coloqu'':186C,382C ''configur'':8A,17A,26B,48B,104C,158C,228C,300C,424C ''configuraco'':354C ''confirm'':133C,147C,235C,329C,343C,431C ''contr'':255C,451C ''contrat'':257C,453C ''copi'':171C,367C ''copie-'':170C,366C ''credenc'':24B,46B,72C,200C,268C,396C ''credencial'':107C,303C ''cri'':2A,11A ''crm'':96C,129C,292C,325C ''códig'':191C ''desenvolv'':132C,328C ''disponiv'':338C ''disponív'':142C ''document'':38B ''documentaca'':60B ''emit'':68C,264C ''endpoint'':40B,62B ''endpoints'':93C,126C,289C,322C ''entend'':19B,41B ''entreg'':27B,49B ''envi'':98C,294C ''escolh'':218C,414C ''escop'':21B,43B,140C,336C ''esta'':337C ''event'':29B,51B,99C,113C,220C,295C,309C,416C ''explicit'':80C,276C ''frontend'':190C,386C ''ger'':167C,363C ''https'':217C,413C ''id'':115C,153C,210C,231C,311C,349C,406C,427C ''idempotent'':226C,422C ''indic'':175C,371C ''integr'':37B,63C,75C,150C,164C,249C ''integraca'':59B,346C,360C,445C ''integraco'':259C,271C ''intern'':94C,127C,290C,323C ''lib'':123C,319C ''liber'':79C,152C,166C,258C,275C,348C,362C,454C ''login'':85C,281C ''mantenh'':223C,419C ''mensag'':194C,390C ''moment'':174C,370C ''nao'':278C,285C,318C ''necessari'':417C ''necessári'