INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000202', 'Pipeline e leads', 'Como criar um lead no Pipeline?', 'A criação manual registra uma nova oportunidade no funil. O formulário separa dados de contato, pessoa, interesse e gestão. A disponibilidade de campos e ações respeita a permissão de criação de leads do usuário.', NULL, NULL, 20, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.608974+00', 'como-criar-um-lead-no-pipeline', 'Abra o formulário de novo lead, preencha os dados essenciais e salve a oportunidade na etapa correta.', 'pipeline', '{"criar lead","novo lead","cadastrar lead","adicionar contato",oportunidade,pipeline}', 'all', '/crm/pipelines?new=lead', 'Criar lead', '[{"id": "lead-create-1", "body": "No Pipeline, use o botão Novo lead. O link abaixo já abre o mesmo fluxo quando seu usuário possui permissão.", "title": "Abra o formulário", "imageAlt": "Formulário Novo lead do Vimob", "imageUrl": "/help/screenshots/criar-lead.png", "actionHref": "/crm/pipelines?new=lead", "actionLabel": "Abrir novo lead", "annotations": [{"x": 96, "y": 4, "label": "1", "title": "Feche o formulário sem salvar"}, {"x": 50, "y": 25, "label": "2", "title": "Comece pelos dados essenciais do contato"}], "imageCaption": "O formulário separa contato, perfil, interesse e gestão antes de salvar o lead."}, {"id": "lead-create-2", "body": "Preencha o nome e, quando disponíveis, telefone e e-mail. Use dados reais e revise o DDD para evitar duplicidade ou falha no WhatsApp.", "title": "Informe o contato"}, {"id": "lead-create-3", "body": "Selecione pipeline, etapa, responsável ou equipe e informe os imóveis de interesse quando fizer sentido. Esses vínculos determinam onde a oportunidade aparece e quem poderá atendê-la.", "title": "Complete interesse e gestão"}, {"id": "lead-create-4", "body": "Depois de salvar, o lead aparece no Pipeline. Abra o card para registrar atividades, agenda, feedback, tags, anexos e histórico.", "title": "Salve e abra o lead"}]', '{como-abrir-e-entender-o-detalhe-de-um-lead,como-mover-um-lead-entre-etapas,como-pesquisar-e-filtrar-leads-no-pipeline}', 5, '2026-10-15 03:47:57.224079+00', '''/crm/pipelines'':143C,372C ''/help/screenshots/criar-lead.png'':141C,370C ''1'':108C,156C,337C,385C ''2'':168C,194C,397C,423C ''25'':166C,395C ''3'':229C,458C ''4'':154C,268C,383C,497C ''50'':164C,393C ''96'':152C,381C ''abaix'':119C,348C ''abra'':13B,40B,131C,278C,293C,360C,507C,522C ''abre'':121C,350C ''abrir'':147C,376C ''aco'':323C ''actionhref'':142C,371C ''actionlabel'':146C,375C ''adicion'':36B,63B ''agend'':284C,513C ''anex'':287C,516C ''annotations'':150C,379C ''antes'':185C,414C ''aparec'':252C,275C,481C,504C ''atend'':257C,486C ''atende-l'':485C ''atendê-l'':256C ''ativ'':283C,512C ''açõ'':94C ''body'':109C,195C,230C,269C,338C,424C,459C,498C ''bota'':343C ''botã'':114C ''cadastr'':34B,61B ''camp'':92C,321C ''card'':280C,509C ''comec'':170C,399C ''complet'':260C,489C ''contat'':37B,64B,84C,175C,180C,224C,313C,404C,409C,453C ''corret'':29B,56B ''creat'':107C,193C,228C,267C,336C,422C,457C,496C ''cri'':2A,8A,30B,57B ''criaca'':300C,328C ''criaçã'':71C,99C ''dad'':21B,48B,82C,172C,208C,311C,401C,437C ''ddd'':213C,442C ''determin'':248C,477C ''disponibil'':90C,319C ''disponiv'':430C ''disponív'':201C ''duplic'':216C,445C ''e-mail'':204C,433C ''equip'':236C,465C ''essenc'':22B,49B,173C,402C ''etap'':28B,55B,233C,462C ''evit'':215C,444C ''falh'':218C,447C ''fech'':158C,387C ''feedback'':285C,514C ''fiz'':244C,473C ''flux'':124C,353C ''formulari'':42B,309C,362C,364C,389C,407C ''formulári'':15B,80C,133C,135C,160C,178C ''funil'':78C,307C ''gesta'':317C,413C,492C ''gestã'':88C,184C,263C ''histor'':518C ''histór'':289C ''id'':104C,190C,225C,264