INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000205', 'Agenda', 'Como criar e editar um agendamento?', 'A Agenda permite criar ligações, e-mails, reuniões, tarefas, mensagens e visitas. Um agendamento pode ter data, duração, dia inteiro, recorrência, responsável, equipe, visibilidade, lead e imóvel relacionado.', NULL, NULL, 50, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.608974+00', 'como-criar-e-editar-um-agendamento', 'Crie compromissos completos, vincule o lead e acompanhe o trabalho no calendário.', 'schedule', '{agenda,agendamento,evento,tarefa,visita,reunião,ligação,compromisso}', 'all', '/agenda', 'Abrir Agenda', '[{"id": "schedule-1", "body": "Na Agenda, clique em Novo agendamento ou selecione um horário disponível no calendário.", "title": "Abra Novo agendamento", "imageAlt": "Painel de criação de agendamento no Vimob", "imageUrl": "/help/screenshots/novo-agendamento.png", "actionHref": "/agenda", "actionLabel": "Abrir Agenda", "annotations": [{"x": 76, "y": 5, "label": "1", "title": "Escolha o tipo da atividade"}, {"x": 75, "y": 94, "label": "2", "title": "Revise os dados e adicione o compromisso"}], "imageCaption": "O painel reúne título, tipo, período, responsáveis, visibilidade e vínculo com o lead."}, {"id": "schedule-2", "body": "Escolha a atividade, informe título, início e duração. Ative dia inteiro ou recorrência somente quando o compromisso exigir.", "title": "Defina tipo, período e recorrência"}, {"id": "schedule-3", "body": "Selecione responsável, equipe, visibilidade e o lead relacionado. O imóvel é opcional e depende do módulo de imóveis.", "title": "Vincule pessoas e contexto"}, {"id": "schedule-4", "body": "Clique no evento para abrir os detalhes. Usuários autorizados podem editar, arrastar, redimensionar, concluir, reabrir ou excluir.", "title": "Edite ou conclua"}]', '{como-conectar-o-google-agenda,como-acompanhar-tarefas-e-cadencias}', 5, '2026-10-15 03:47:57.224079+00', '''-1'':85C,272C ''-2'':162C,349C ''-3'':190C,377C ''-4'':217C,404C ''/agenda'':115C,302C ''/help/screenshots/novo-agendamento.png'':113C,300C ''1'':125C,312C ''2'':137C,324C ''5'':123C,310C ''75'':133C,320C ''76'':121C,308C ''94'':135C,322C ''abra'':101C,288C ''abrir'':117C,223C,304C,410C ''acompanh'':20B,40B ''actionhref'':114C,301C ''actionlabel'':116C,303C ''adicion'':143C,330C ''agend'':6A,12A,25B,26B,45B,46B,53C,55C,68C,88C,92C,103C,109C,118C,240C,242C,255C,275C,279C,290C,296C,305C ''annotations'':119C,306C ''arrast'':230C,417C ''ativ'':131C,166C,172C,318C,353C,359C ''autoriz'':227C,414C ''body'':86C,163C,191C,218C,273C,350C,378C,405C ''calendari'':44B,286C ''calendári'':24B,99C ''cliqu'':89C,219C,276C,406C ''complet'':15B,35B ''compromiss'':14B,32B,34B,52B,145C,180C,332C,367C ''conclu'':232C,239C,419C,426C ''context'':214C,401C ''cri'':2A,8A,13B,33B,57C,244C ''criaca'':294C ''criaçã'':107C ''dad'':141C,328C ''dat'':71C,258C ''defin'':183C,370C ''depend'':205C,392C ''detalh'':225C,412C ''dia'':73C,173C,260C,360C ''dispon'':97C ''disponivel'':284C ''duraca'':259C,358C ''duraçã'':72C,171C ''e-mails'':59C,246C ''edit'':4A,10A,229C,237C,416C,424C ''equip'':77C,194C,264C,381C ''escolh'':127C,164C,314C,351C ''event'':27B,47B,221C,408C ''exclu'':235C,422C ''exig'':181C,368C ''horari'':283C ''horári'':96C ''id'':83C,160C,188C,215C,270C,347C,375C,402C ''imagealt'':104C,291C ''imagecaption'':146C,333C ''imageurl'':112C,299C ''imov'':396C ''imovel'':268C,388C ''imóv'':209C ''imóvel'':81C,201C ''inform'':167C,354C ''inici'':356C ''inteir'':74C,174C,261C,361C ''iníci'':169C ''label'':124C,136C,311C,323C ''lead'':18B,38B,79C,159C,198C,266C,346C,385C ''ligaca'':51B ''ligaco'':245C ''ligaçã'':31B ''ligaçõ'':58C ''mails'':61C,248C ''mensagens'':6