INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('10000000-0000-4000-8000-000000000208', 'Automações', 'Como criar uma automação?', 'O construtor visual de automações funciona no desktop. Você escolhe um gatilho, conecta ações e condições, simula o fluxo, salva e só então ativa. No celular é possível consultar lista, modelos e histórico, mas não montar o diagrama.', NULL, NULL, 80, true, '2026-10-15 03:47:56.983717+00', '2026-10-15 03:47:57.608974+00', 'como-criar-uma-automacao', 'Crie um fluxo determinístico, teste o caminho e ative somente depois de validar a execução.', 'automations', '{"criar automação","nova automação",fluxo,gatilho,condição,ação,follow-up,builder}', 'all', '/automations?tab=automations', 'Abrir Automações', '[{"id": "automation-create-1", "body": "Abra Automações e clique em Nova automação. O construtor visual não fica disponível no celular.", "title": "Inicie no desktop", "imageAlt": "Tela de criação de automação no Vimob", "imageUrl": "/help/screenshots/nova-automacao.png", "actionHref": "/automations?tab=automations", "actionLabel": "Abrir Automações", "annotations": [{"x": 93, "y": 4, "label": "1", "title": "Salve depois de revisar e simular"}, {"x": 10, "y": 19, "label": "2", "title": "Arraste os blocos para montar o fluxo"}], "imageCaption": "O construtor mostra gatilho, blocos disponíveis, conexões e ações de simular e salvar."}, {"id": "automation-create-2", "body": "Use mensagem recebida, agendamento, mudança de etapa, lead criado, tag adicionada, inatividade ou execução manual.", "title": "Escolha o gatilho"}, {"id": "automation-create-3", "body": "Adicione texto, imagem, vídeo, áudio, condição, espera, webhook, tag ou mudança de etapa. Configure a sessão de WhatsApp e use variáveis como {{lead.name}} e {{lead.phone}} quando necessário.", "title": "Monte o fluxo"}, {"id": "automation-create-4", "body": "Execute o simulador, corrija blocos inválidos, salve o rascunho e ative apenas depois de conferir todos os caminhos.", "title": "Simule, salve e ative"}]', '{como-criar-uma-automacao-a-partir-de-um-modelo,como-acompanhar-execucoes-e-erros-de-automacao}', 7, '2026-10-15 03:47:57.224079+00', '''/automations'':138C,352C ''/help/screenshots/nova-automacao.png'':136C,350C ''1'':106C,150C,320C,364C ''10'':159C,373C ''19'':161C,375C ''2'':163C,190C,377C,404C ''3'':215C,429C ''4'':148C,252C,362C,466C ''93'':146C,360C ''abra'':108C,322C ''abrir'':142C,356C ''aca'':58B ''aco'':291C,395C ''actionhref'':137C,351C ''actionlabel'':141C,355C ''adicion'':202C,217C,416C,431C ''agend'':195C,409C ''annotations'':144C,358C ''apen'':265C,479C ''arrast'':165C,379C ''ativ'':17B,44B,87C,264C,276C,301C,478C,490C ''audi'':435C ''autom'':4A,25B,27B,63C,68C,109C,114C,132C,143C ''automaca'':8A,52B,54B,328C,346C ''automaco'':277C,282C,323C,357C ''automation'':104C,188C,213C,250C,318C,402C,427C,464C ''automation-creat'':103C,187C,212C,249C,317C,401C,426C,463C ''automations'':140C,354C ''açã'':31B ''açõ'':77C,181C ''bloc'':167C,177C,258C,381C,391C,472C ''body'':107C,191C,216C,253C,321C,405C,430C,467C ''build'':35B,62B ''caminh'':15B,42B,271C,485C ''celul'':89C,122C,303C,336C ''cliqu'':111C,325C ''condica'':57B,436C ''condico'':293C ''condiçã'':30B,222C ''condiçõ'':79C ''conect'':76C,290C ''conexo'':393C ''conexõ'':179C ''confer'':268C,482C ''configur'':230C,444C ''construtor'':65C,116C,174C,279C,330C,388C ''consult'':92C,306C ''corrij'':257C,471C ''creat'':105C,189C,214C,251C,319C,403C,428C,465C ''cri'':2A,6A,9B,24B,36B,51B,200C,414C ''criaca'':344C ''criaçã'':130C ''desktop'':71C,126C,285C,340C ''determinist'':39B ''determiníst'':12B ''diagram'':101C,315C ''dispon'':120C ''disponiv'':392C ''disponivel'':334C ''disponív'':178C ''enta'':300C ''entã'':86C ''escolh'':73C,208C,287C,42