INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000219', 'Conversas e WhatsApp', 'Como conectar o WhatsApp?', 'A conexão é criada em Configurações, na área de Integrações do WhatsApp. Informe um nome para a sessão, gere o QR Code e leia com o aparelho correto. O limite de sessões depende do plano e da organização.', NULL, NULL, 190, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.608974+00', 'como-conectar-o-whatsapp', 'Crie uma sessão, leia o QR Code e confira se a conexão ficou pronta para uso.', 'conversations', '{"conectar whatsapp","qr code","nova sessão",instância,evolution,"reconectar whatsapp"}', 'all', '/settings?tab=whatsapp', 'Configurar WhatsApp', '[{"id": "whatsapp-connect-1", "body": "Em Configurações, entre em Integrações e selecione WhatsApp. A área exige o módulo e a permissão de gestão.", "title": "Abra a integração", "imageAlt": "Configuração de uma conexão WhatsApp no Vimob", "imageUrl": "/help/screenshots/conectar-whatsapp.png", "actionHref": "/settings?tab=whatsapp", "actionLabel": "Configurar WhatsApp", "annotations": [{"x": 50, "y": 82, "label": "1", "title": "Abra o fluxo de conexão"}, {"x": 83, "y": 12, "label": "2", "title": "Confira o status atual"}], "imageCaption": "Use Conectar para abrir o fluxo e acompanhe o status atual da integração."}, {"id": "whatsapp-connect-2", "body": "Use um nome que identifique canal, equipe ou finalidade. Isso facilita selecionar a conexão em Conversas e Automações.", "title": "Nomeie a sessão"}, {"id": "whatsapp-connect-3", "body": "No aparelho correto, abra os dispositivos conectados do WhatsApp e leia o código exibido. Aguarde a confirmação do status.", "title": "Leia o QR Code"}, {"id": "whatsapp-connect-4", "body": "Abra Conversas, selecione a sessão e confirme que o histórico e o envio estão disponíveis. Se necessário, use atualizar, recriar ou reconectar.", "title": "Valide a operação"}]', '{como-usar-conversas-no-vimob,como-enviar-texto-audio-e-arquivos-no-whatsapp}', 6, '2026-10-15 03:47:57.224079+00', '''/help/screenshots/conectar-whatsapp.png'':139C,353C ''/settings'':141C,355C ''1'':106C,153C,320C,367C ''12'':163C,377C ''2'':165C,189C,379C,403C ''3'':217C,431C ''4'':247C,461C ''50'':149C,363C ''82'':151C,365C ''83'':161C,375C ''abra'':127C,155C,222C,249C,341C,369C,436C,463C ''abrir'':175C,389C ''acompanh'':179C,393C ''actionhref'':140C,354C ''actionlabel'':144C,358C ''aguard'':233C,447C ''annotations'':147C,361C ''aparelh'':90C,220C,304C,434C ''are'':285C,331C ''atual'':170C,182C,384C,396C ''atualiz'':267C,481C ''autom'':208C ''automaco'':422C ''body'':107C,190C,218C,248C,321C,404C,432C,462C ''canal'':196C,410C ''cod'':15B,28B,41B,54B,85C,242C,299C,456C ''codig'':445C ''conect'':2A,6A,25B,51B,173C,225C,387C,439C ''conexa'':46B,279C,348C,373C,418C ''conexã'':20B,65C,134C,159C,204C ''conf'':17B,43B,167C,381C ''configur'':69C,109C,131C,145C,359C ''configuraca'':345C ''configuraco'':283C,323C ''confirm'':235C,255C,469C ''confirmaca'':449C ''connect'':105C,188C,216C,246C,319C,402C,430C,460C ''convers'':61C,206C,250C,275C,420C,464C ''corret'':91C,221C,305C,435C ''cri'':9B,35B,67C,281C ''códig'':231C ''depend'':96C,310C ''disponiv'':477C ''disponív'':263C ''disposit'':224C,438C ''envi'':261C,475C ''equip'':197C,411C ''esta'':476C ''evolution'':32B,58B ''exib'':232C,446C ''exig'':118C,332C ''facilit'':201C,415C ''fic'':21B,47B ''final'':199C,413C ''flux'':157C,177C,371C,391C ''ger'':82C,296C ''gesta'':339C ''gestã'':125C ''histor'':472C ''histór'':258C ''id'':102C,185C,213C,243C,316C,399C,427C,457C ''identifiqu'':195C,409C ''imagealt'':130C,344C ''imagecaption'':171C,385C ''imageurl'':138C,352C ''inform'':76C,290C ''instanc'':57B ''instânc'':31B ''integr'':73C,112C,129C,184C