INSERT INTO public.help_articles (id, category, title, content, video_url, image_url, display_order, is_active, created_at, updated_at, slug, summary, module_key, search_keywords, visibility, route_href, action_label, steps, related_slugs, estimated_minutes, last_reviewed_at, search_vector) VALUES ('20000000-0000-4000-8000-000000000224', 'Usuários e permissões', 'Como convidar um usuário?', 'Convites são enviados por e-mail e não geram senha pronta. Escolha a função inicial admin ou usuário. O destinatário usa o link para criar o acesso ou associar uma conta existente à organização.', NULL, NULL, 240, true, '2026-10-15 03:47:57.224079+00', '2026-10-15 03:47:57.608974+00', 'como-convidar-um-usuario', 'Envie um convite seguro por e-mail e acompanhe os estados pendente, expirado ou aceito.', 'users', '{"convidar usuário","adicionar usuário","novo usuário","convite email",equipe,admin}', 'all', '/settings?tab=team', 'Abrir Usuários', '[{"id": "invite-1", "body": "Em Configurações, entre na aba Usuários. A ação exige permissão de gestão de usuários.", "title": "Abra Usuários", "imageAlt": "Painel Convidar usuário do Vimob", "imageUrl": "/help/screenshots/convidar-usuario.png", "actionHref": "/settings?tab=team", "actionLabel": "Abrir Usuários", "annotations": [{"x": 50, "y": 18, "label": "1", "title": "Informe e-mail e função"}, {"x": 86, "y": 39, "label": "2", "title": "Envie o convite"}], "imageCaption": "Informe o e-mail, escolha a função inicial e envie o convite sem compartilhar senhas."}, {"id": "invite-2", "body": "Revise o endereço e escolha admin ou usuário. Permissões individuais podem ser ajustadas depois.", "title": "Informe e-mail e função"}, {"id": "invite-3", "body": "O convite aparece como pendente. Se expirar, reenviar cria um novo link válido por sete dias; cancelar invalida o acesso pendente.", "title": "Envie e acompanhe"}, {"id": "invite-4", "body": "Uma pessoa nova informa nome, WhatsApp, senha e aceita os documentos legais. Quem já possui conta pode aceitar usando o acesso existente.", "title": "Oriente o destinatário"}]', '{como-configurar-permissoes-e-remover-usuarios,como-criar-e-gerenciar-equipes}', 6, '2026-10-15 03:47:57.224079+00', '''-1'':101C,300C ''-2'':178C,377C ''-3'':203C,402C ''-4'':232C,431C ''/help/screenshots/convidar-usuario.png'':127C,326C ''/settings'':129C,328C ''1'':141C,340C ''18'':139C,338C ''2'':154C,353C ''39'':152C,351C ''50'':137C,336C ''86'':150C,349C ''aba'':107C,306C ''abra'':118C,317C ''abrir'':133C,332C ''aca'':309C ''aceit'':24B,50B,242C,251C,441C,450C ''acess'':91C,224C,254C,290C,423C,453C ''acompanh'':18B,44B,229C,428C ''actionhref'':128C,327C ''actionlabel'':132C,331C ''adicion'':27B,53B ''admin'':34B,60B,80C,185C,279C,384C ''ajust'':192C,391C ''annotations'':135C,334C ''aparec'':207C,406C ''assoc'':93C,292C ''açã'':110C ''body'':102C,179C,204C,233C,301C,378C,403C,432C ''cancel'':221C,420C ''compartilh'':174C,373C ''configur'':104C ''configuraco'':303C ''cont'':95C,249C,294C,448C ''convid'':2A,6A,25B,51B,122C,321C ''convit'':11B,31B,37B,57B,64C,158C,172C,206C,263C,357C,371C,405C ''cri'':89C,213C,288C,412C ''destinatari'':283C,458C ''destinatári'':84C,259C ''dias'':220C,419C ''document'':244C,443C ''e-mail'':14B,40B,68C,144C,162C,196C,267C,343C,361C,395C ''email'':32B,58B ''enderec'':182C,381C ''envi'':9B,35B,66C,156C,170C,227C,265C,355C,369C,426C ''equip'':33B,59B ''escolh'':76C,165C,184C,275C,364C,383C ''estad'':20B,46B ''exig'':111C,310C ''existent'':96C,255C,295C,454C ''expir'':22B,48B,211C,410C ''funca'':277C,347C,366C,399C ''funçã'':78C,148C,167C,200C ''ger'':73C,272C ''gesta'':313C ''gestã'':114C ''id'':99C,176C,201C,230C,298C,375C,400C,429C ''imagealt'':120C,319C ''imagecaption'':159C,358C ''imageurl'':126C,325C ''individu'':189C,388C ''inform'':143C,160C,195C,237C,342C,359C,394C,436C ''inicial'':79C,168C,278C,367C ''inval'':222C,421C ''invit'':100C,177C,202C,231C,299C,376C,401C,430C ''ja'':446C ''label'':140C,153C,339C,352C ''leg'':245C,444C ''link'':87C,216C,286C,